export default function createBehavior(api) {
  let panel = null
  let timer = 0
  let lastPulse = false
  let status = 'Initializing Steam API…'
  let logs = []
  let lobbies = []
  let running = true
  let busy = false
  const disposers = []
  const DEMO_FILE = 'miniforge-lobby-example.txt'

  function log(message) {
    logs.unshift(String(message))
    logs = logs.slice(0, 5)
    refresh()
  }

  function refresh() {
    if (!panel) return
    const st = api.net.getStats()
    const mode = api.steam.getMode()
    const lobby = api.steam.getLobby()
    panel.querySelector('[data-status]').textContent = status
    panel.querySelector('[data-mode]').textContent = mode === 'native' ? 'NATIVE STEAMWORKS' : mode === 'local-debug' ? 'LOCAL DEBUG — NOT STEAM' : 'STEAM UNAVAILABLE'
    panel.querySelector('[data-mode]').style.color = mode === 'native' ? '#4ade80' : mode === 'local-debug' ? '#fbbf24' : '#fca5a5'
    panel.querySelector('[data-peer]').textContent = `${st.connected ? 'CONNECTED' : 'OFFLINE'} · ${st.peerCount} player(s) · ${st.room}`
    panel.querySelector('[data-lobby]').textContent = lobby ? `${lobby.name} (${lobby.members.length}/${lobby.maxMembers}) ID: ${lobby.id}` : 'No lobby joined'
    panel.querySelector('[data-log]').textContent = logs.join('\n')
    const select = panel.querySelector('[data-lobbies]')
    const selected = select.value
    select.replaceChildren()
    for (const item of lobbies) {
      const option = document.createElement('option')
      option.value = item.id
      option.textContent = `${item.name} — ${item.members.length}/${item.maxMembers} (${item.id})`
      select.appendChild(option)
    }
    if (lobbies.some(item => item.id === selected)) select.value = selected
    panel.querySelectorAll('button').forEach(button => {
      button.disabled = busy || mode === 'unavailable' || (button.dataset.action === 'join' && !lobbies.length)
    })
  }

  async function startNet(lobby) {
    // No network transport starts until Steam lobby creation/join has succeeded.
    const ok = await api.net.connect({mode:'steam-p2p',room:lobby.name || lobby.id})
    if (!ok) throw new Error(api.net.getStats().lastError || 'Could not join P2P room')
    status = 'Connected to lobby ' + lobby.name
    log('P2P connected as ' + api.net.peerId())
    await api.steam.setRichPresence('status', 'In demo lobby')
    await api.steam.unlockAchievement('ACH_LOBBY_JOINED')
  }

  async function action(name) {
    if (busy || api.steam.getMode() === 'unavailable') return
    busy = true
    refresh()
    try {
      if (name === 'create') {
        api.net.disconnect()
        await api.steam.leaveLobby()
        const lobby = await api.steam.createLobby({name:'Miniforge Demo',maxMembers:4,type:'public'})
        await startNet(lobby)
      } else if (name === 'find') {
        lobbies = await api.steam.listLobbies()
        log('Found ' + lobbies.length + ' lobby/lobbies')
      } else if (name === 'join') {
        const id = panel.querySelector('[data-lobbies]').value
        if (!id) throw new Error('Select a lobby first')
        api.net.disconnect()
        await api.steam.leaveLobby()
        const lobby = await api.steam.joinLobby(id)
        if (!lobby) throw new Error('Lobby missing or full — refresh list')
        await startNet(lobby)
      } else if (name === 'leave') {
        api.net.disconnect()
        await api.steam.leaveLobby()
        status = 'Left the lobby'
        log(status)
      } else if (name === 'ping') {
        if (!api.net.getStats().connected) throw new Error('Join a lobby first')
        api.net.rpc('steam-demo:pulse', {ts:Date.now()}, 'all')
      } else if (name === 'write') {
        const ok = await api.steam.cloudWrite(DEMO_FILE, 'Miniforge demo saved at ' + new Date().toISOString())
        log(ok ? 'Saved demo file (' + api.steam.getMode() + ')' : 'Cloud write failed')
      } else if (name === 'read') {
        const content = await api.steam.cloudRead(DEMO_FILE)
        log(content === null ? 'Cloud file not found' : 'Cloud: ' + content)
      }
    } catch (err) {
      status = 'Error: ' + String(err?.message || err)
      log(status)
    } finally {
      busy = false
      refresh()
    }
  }

  return {
    onStart() {
      panel = document.createElement('section')
      panel.style.cssText = 'position:fixed;top:10px;left:10px;z-index:40;width:min(360px,45vw);max-height:85vh;overflow:auto;padding:12px;border:1px solid #475569;border-radius:10px;background:rgba(15,23,42,.94);color:#e2e8f0;font:12px/1.5 system-ui,sans-serif;pointer-events:auto;'
      panel.innerHTML = `
        <div style="font-weight:bold;font-size:15px">Steam Lobby / P2P example</div>
        <div data-mode style="font-weight:bold;margin:4px 0"></div>
        <div data-status></div>
        <div data-peer style="color:#94a3b8"></div>
        <div data-lobby style="margin:5px 0;overflow-wrap:anywhere"></div>
        <div style="display:flex;flex-wrap:wrap;gap:5px;margin:8px 0">
          <button data-action="create">Create lobby</button>
          <button data-action="find">Find lobbies</button>
          <button data-action="join">Join selected</button>
          <button data-action="leave">Leave</button>
          <button data-action="ping">Send RPC</button>
          <button data-action="write">Cloud write</button>
          <button data-action="read">Cloud read</button>
        </div>
        <select data-lobbies style="width:100%;background:#0f172a;color:#e2e8f0;border:1px solid #334155;padding:4px"></select>
        <pre data-log style="white-space:pre-wrap;color:#94a3b8;font:11px monospace;margin-top:8px"></pre>
        <div style="color:#fbbf24;font-size:11px;margin-top:5px">Local Debug uses BroadcastChannel/localStorage, NOT the Steam service. Native Steamworks is unavailable until a real SDK bridge is added.</div>
      `
      document.body.appendChild(panel)
      panel.querySelectorAll('button').forEach(button => {
        const click = () => { void action(button.dataset.action) }
        button.addEventListener('click',click)
        disposers.push(() => button.removeEventListener('click',click))
      })
      disposers.push(api.net.onPeerJoin(id => log('Peer joined: ' + id.slice(-6))))
      disposers.push(api.net.onPeerLeave(id => log('Peer left: ' + id.slice(-6))))
      disposers.push(api.net.onRpc('steam-demo:pulse', (_payload, sender) => log('RPC pulse from ' + String(sender).slice(-6))))
      refresh()
      void api.steam.init(api.project.settings.steam?.appId || 480).then(() => {
        if (!running) return
        status = api.steam.getMode() === 'unavailable'
          ? 'Native Steamworks missing: no fake connection in exported games'
          : api.steam.getMode() === 'local-debug'
            ? 'Local Debug ready. Open TWO editor preview tabs to test lobby discovery.'
            : 'Native Steam ready'
        refresh()
      }).catch(err => { if (running) { status = String(err); refresh() } })
    },
    onUpdate(dt) {
      timer += dt
      if (timer >= 0.4) { timer = 0; refresh() }
      const pressed = api.input.pressed('Jump')
      if (pressed && !lastPulse && api.net.getStats().connected) api.net.rpc('steam-demo:pulse', {ts:Date.now()}, 'all')
      lastPulse = pressed
    },
    onDestroy() {
      running = false
      api.net.disconnect()
      for (const fn of disposers.splice(0)) if (typeof fn === 'function') fn()
      panel?.remove()
      panel = null
    },
  }
}
